import {holes,holeMap,boardEdges,occupied,footprint,defaults,validPlacement} from './breadboard.mjs';
import {compile,execute} from './runtime.mjs';import {examples} from './examples.mjs';import {definitions,lessonWires,connected as graphConnected,checkCircuit as graphCheck,validateProject as oldValidate} from './circuit.mjs';import {Display} from './display.mjs';import {createTable} from './board-scene.mjs';
const $=id=>document.getElementById(id),editor=$('code'),canvas=$('oled'),ctx=canvas.getContext('2d'),display=new Display();let table,wires=[],pending=null,selected=null,controller=null,runGeneration=0,ready=false,sda=5,scl=4,modes={},values={},logs=[],lastProgram='';
display.render(ctx,false);editor.value=examples.eyes;const numbers=()=>{$('numbers').textContent=Array.from({length:editor.value.split('\n').length},(_,i)=>i+1).join('\n');};numbers();
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4000);}
function log(s){logs.push(String(s));logs=logs.slice(-150);$('log').textContent=logs.join('\n');$('log').scrollTop=$('log').scrollHeight;}
function blackScreen(){display.render(ctx,false);table?.refreshScreen();}
function stop(message='已停止'){controller?.abort();controller=null;runGeneration++;ready=false;blackScreen();table?.led(false);$('ledstate').textContent='板载 LED：关闭';$('run').disabled=false;$('stop').disabled=true;$('status').textContent=message;}
const network=w=>[...w,...boardEdges(table?.state()??[])];
function connected(w,a,b){return graphConnected(network(w),a,b);}
function checkCircuit(w,a,sda=5,scl=4){return graphCheck(network(w),a,sda,scl);}
function validateProject(p){if(p?.version!==2)throw Error('请使用面包板版本的作品文件；旧版 .ino 代码仍可打开');if(typeof p.code!=='string'||p.code.length>50000||!Array.isArray(p.parts)||p.parts.length>5||!Array.isArray(p.wires)||p.wires.length>80)throw Error('作品格式无效');const ps=[];for(const v of p.parts){if(!definitions.some(d=>d.id===v.id)||ps.some(d=>d.id===v.id)||!Number.isInteger(v.row)||!validPlacement(ps,v.id,v.row))throw Error('零件位置无效');ps.push(v);}const used=occupied(ps);for(const w of p.wires){if(!holeMap.has(w.a)||!holeMap.has(w.b)||w.a===w.b||used.has(w.a)||used.has(w.b))throw Error('孔位无效或被重复占用');used.add(w.a);used.add(w.b);}return p;}
function freeHole(pin){const edge=boardEdges(table.state()).find(e=>e.a===pin);if(!edge)return null;const net=holeMap.get(edge.b).net,used=occupied(table.state(),wires);return holes.find(h=>h.net===net&&!used.has(h.id))?.id;}
const active=()=>table?table.state().map(p=>p.id):[];
function selectedPart(id){selected=id;$('selected').hidden=!id;if(id)$('selectedname').textContent=definitions.find(d=>d.id===id).name;}
function wireName(id){if(holeMap.has(id))return '孔 '+id.slice(3);const[part,pin]=id.split(':');return definitions.find(d=>d.id===part).name+' '+pin;}
function updateGuide(){if(!table)return;const done=lessonWires.map(([a,b])=>connected(wires,a,b));let i=done.indexOf(false);$('steps').replaceChildren(...done.map(v=>{let el=document.createElement('span');el.className=v?'done':'';return el;}));if(i<0){$('step-title').textContent='4 / 4 · 屏幕接线完成';$('step-text').textContent='点击运行，让眼睛眨起来。试试把 delay(1500) 改成 delay(500)。';table.highlight([],pending);}else{$('step-title').textContent=`${i+1} / 4 · ${lessonWires[i][2]}`;const pair=lessonWires[i].slice(0,2).map(freeHole);$('step-text').textContent=lessonWires[i][3]+' 可用孔：'+pair.map(p=>p?p.slice(3):'请先放入零件 / 释放孔位').join(' ↔ ');table.highlight(pending?holes.filter(h=>connected(wires,pending,h.id)).map(h=>h.id):pair.filter(Boolean),pending);}$('wirecount').textContent=wires.length;$('wirelist').replaceChildren(...wires.map((w,i)=>{const row=document.createElement('div');row.className='wirerow';const txt=document.createElement('span');txt.textContent=wireName(w.a)+' ↔ '+wireName(w.b);const b=document.createElement('button');b.textContent='删除';b.onclick=()=>{stop('接线已更改');wires.splice(i,1);updateWires();};row.append(txt,b);return row;}));}
function updateWires(){table.setWires(wires);updateGuide();}
function connect(id){if(!holeMap.has(id))return;const net=network(wires);table.highlight(holes.filter(h=>graphConnected(net,id,h.id)).map(h=>h.id),id);if(occupied(table.state(),wires).has(id)){toast('此孔已被针脚或插头占用，请选同组的其他空孔。');return;}if(controller){toast('先停止运行，再修改接线。');return;}if(!pending){pending=id;updateGuide();toast('已选 '+wireName(id)+'，再点击终点针脚');return;}if(pending===id){pending=null;updateGuide();return;}if(wires.some(w=>(w.a===pending&&w.b===id)||(w.b===pending&&w.a===id))){toast('这两个针脚已经连接');pending=null;updateGuide();return;}wires.push({a:pending,b:id});pending=null;updateWires();const check=checkCircuit(wires,active());if(check.errors.length)toast(check.errors[0]);}
function refresh(){const c=checkCircuit(wires,active(),sda,scl);display.render(ctx,ready&&c.ready);table.refreshScreen();}
const counts={'Wire.begin':[2],'display.begin':[2],'display.clearDisplay':[0],'display.display':[0],'display.drawPixel':[3],'display.drawLine':[5],'display.drawRect':[5],'display.fillRect':[5],'display.drawCircle':[4],'display.fillCircle':[4],'display.drawRoundRect':[6],'display.fillRoundRect':[6],'display.setCursor':[2],'display.setTextSize':[1],'display.setTextColor':[1,2],'display.print':[1],'display.println':[0,1],'display.invertDisplay':[1],'pinMode':[2],'digitalWrite':[2],'digitalRead':[1],'Serial.begin':[1],'Serial.print':[1],'Serial.println':[0,1]};
function hardware(name,a){if(!counts[name]?.includes(a.length))throw Error(name+'() 参数个数不正确');if(a.some(v=>typeof v==='number'&&(!Number.isFinite(v)||Math.abs(v)>1000000)))throw Error('数值超出初版范围');
 if(name==='Wire.begin'){[sda,scl]=a;if(!Number.isInteger(sda)||!Number.isInteger(scl)||sda===scl)throw Error('SDA 与 SCL 要使用不同的引脚编号');return 1;}
 if(name==='display.begin'){const c=checkCircuit(wires,active(),sda,scl);ready=c.ready&&a[0]===2&&a[1]===0x3c;if(!ready)log(!c.powered?'屏幕未供电：请检查 GND 和 VCC。':!c.bus?`屏幕信号线不匹配：代码 SDA=${sda}、SCL=${scl}。`:'屏幕地址应为 0x3C，供电模式使用 SSD1306_SWITCHCAPVCC。');return ready?1:0;}
 if(name==='display.clearDisplay'){display.pixels.fill(0);return 0;}if(name==='display.display'){refresh();return 0;}
 if(name.startsWith('display.')){const f=name.slice(8);if(['drawPixel','drawLine','drawRect','fillRect','drawCircle','fillCircle','drawRoundRect','fillRoundRect'].includes(f)&&a.some(v=>typeof v!=='number'))throw Error('绘图参数需要数字');switch(f){case'drawPixel':display.pixel(...a);break;case'drawLine':display.line(...a);break;case'drawRect':display.rect(...a);break;case'fillRect':display.rect(...a,true);break;case'drawCircle':display.circle(...a);break;case'fillCircle':display.circle(...a,true);break;case'drawRoundRect':display.rect(a[0],a[1],a[2],a[3],a[5],false,a[4]);break;case'fillRoundRect':display.rect(a[0],a[1],a[2],a[3],a[5],true,a[4]);break;case'setCursor':[display.x,display.y]=a;break;case'setTextSize':if(!Number.isInteger(a[0])||a[0]<1||a[0]>8)throw Error('文字大小请使用 1–8');display.size=a[0];break;case'setTextColor':display.color=a[0];break;case'print':display.print(a[0]);break;case'println':display.print(a[0]??'',true);break;case'invertDisplay':display.invert=!!a[0];refresh();break;}return 0;}
 if(name==='pinMode'){if(![0,1,2].includes(a[1]))throw Error('pinMode 模式无效');modes[a[0]]=a[1];return 0;}if(name==='digitalWrite'){if(modes[a[0]]!==1)throw Error(`请先设置 pinMode(${a[0]}, OUTPUT)`);values[a[0]]=a[1]?1:0;if(a[0]===8){table.led(!a[1]);$('ledstate').textContent='板载 LED：'+(a[1]?'关闭':'点亮');}return 0;}if(name==='digitalRead')return values[a[0]]??(modes[a[0]]===2?1:0);if(name==='Serial.begin')return 0;if(name.startsWith('Serial.')){log(a[0]??'');return 0;}throw Error('尚不支持 '+name);
}
async function run(){if(!table){toast('零件尚未加载完');return;}stop();logs=[];$('log').textContent='';display.reset();sda=5;scl=4;modes={};values={};const generation=runGeneration;try{const program=compile(editor.value);const check=checkCircuit(wires,active());if(check.errors.length)throw Error(check.errors.join('\n'));lastProgram=editor.value;controller=new AbortController();$('run').disabled=true;$('stop').disabled=false;$('status').textContent='运行中';log('语法检查通过，正在执行 setup() / loop()。');const own=controller;await execute(program,{call:hardware},own.signal);}catch(e){if(e.message==='STOPPED'||generation!==runGeneration)return;stop('运行出错');log('错误：'+e.message);const m=/第 (\d+) 行/.exec(e.message);if(m){let start=editor.value.split('\n').slice(0,+m[1]-1).join('\n').length;editor.focus();editor.setSelectionRange(start,start+editor.value.split('\n')[+m[1]-1].length+1);}}}
for(const d of definitions){const b=document.createElement('button');b.className='partbtn';const sw=document.createElement('span');sw.className='partswatch';sw.style.background=d.color;const span=document.createElement('span'),bold=document.createElement('b'),small=document.createElement('small');bold.textContent=d.name;small.textContent=d.detail;span.append(bold,small);b.append(sw,span);b.onclick=()=>{if(!table)return;if(controller)stop('零件已更改');table.setActive(d.id,true);table.select(d.id);updateGuide();if(d.id==='amp'||d.id==='mic'||d.id==='speaker')toast('此零件目前支持摆放与接线，音频模拟将在后续加入。');};$('catalog').append(b);}
$('run').onclick=run;$('stop').onclick=()=>stop();$('clearlog').onclick=()=>{logs=[];$('log').textContent='';};$('help').onclick=()=>$('helpdialog').showModal();$('top').onclick=()=>{table?.setMode('top');$('top').classList.add('active');$('three').classList.remove('active');$('scenehint').textContent='拖动零件换行 · 点击两个空孔接线 · 滚轮放大';};$('xray').onclick=()=>{const on=$('xray').getAttribute('aria-pressed')!=='true';$('xray').setAttribute('aria-pressed',String(on));table?.setXray(on);$('xray').classList.toggle('active',on);};$('three').onclick=()=>{pending=null;table?.setMode('three');$('three').classList.add('active');$('top').classList.remove('active');$('scenehint').textContent='左键拖动零件 · 右键旋转视角 · 滚轮缩放';};$('resetview').onclick=()=>table?.center();$('rotate').onclick=()=>{stop('零件已更改');table?.rotate();};$('flip').onclick=()=>{stop('零件已更改');table?.flip();};$('remove').onclick=()=>{if(!selected)return;stop('零件已收回');table.setActive(selected,false);wires=wires.filter(w=>![w.a,w.b].some(p=>p.startsWith(selected+':')));pending=null;table.select(null);updateWires();};$('undo').onclick=()=>{stop('已撤销接线');wires.pop();pending=null;updateWires();};
function lesson(){stop();wires=[];pending=null;table.restore(definitions.filter(d=>['oled','esp'].includes(d.id)).map(d=>({id:d.id,pos:d.pos,rotation:0,flipped:false})));table.select(null);table.center();updateWires();}
$('lesson').onclick=()=>{if(confirm('恢复两块板的初始位置，并清空接线？代码会保留。'))lesson();};$('loadexample').onclick=()=>{if(editor.value!==lastProgram&&editor.value!==examples.eyes&&!confirm('载入示例会替换编辑器中的代码，是否继续？'))return;stop('示例已载入');editor.value=examples[$('example').value];lastProgram=editor.value;numbers();};
editor.addEventListener('input',()=>{numbers();if(controller)stop('代码已修改，请重新运行');});editor.addEventListener('scroll',()=>{$('numbers').scrollTop=editor.scrollTop;});editor.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText('  ',start,end,'end');editor.dispatchEvent(new Event('input'));}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}});
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function project(){return{version:2,code:editor.value,parts:table.state(),wires};}
$('save').onclick=()=>{if(!table)return;download('desk-buddy.json',JSON.stringify(project(),null,2),'application/json');toast('作品已保存到下载文件夹');};$('export').onclick=()=>download('desk_buddy.ino',editor.value,'text/plain');$('open').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>200000)throw Error('文件太大');const data=await file.text();if(!confirm('打开文件会替换当前作品中的相应内容，是否继续？'))return;if(file.name.endsWith('.ino')){stop('代码已打开');editor.value=data;}else{const p=validateProject(JSON.parse(data));stop('作品已打开');editor.value=p.code;table.restore(p.parts);wires=p.wires.map(w=>({a:w.a,b:w.b}));pending=null;updateWires();}numbers();lastProgram=editor.value;}catch(e){toast('打开失败：'+e.message);}$('file').value='';};
try{table=await createTable($('viewport'),canvas,{pin:connect,select:selectedPart,change:()=>{stop('孔位已更改，请重新运行');pending=null;updateWires();},message:toast});lesson();$('loading').remove();}catch(e){$('loading').textContent='三维零件加载失败，请刷新页面。'+e.message;log(e.message);$('run').disabled=true;}
window.addEventListener('keydown',e=>{if(e.key==='Escape'){pending=null;updateGuide();}});
// Optional browser tool interface uses the exact same state and validation.
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'read_desk_buddy_project',description:'Read the current virtual Desk Buddy code, parts and wiring.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){if(!table)throw Error('尚未加载完成');return project();}},{name:'check_desk_buddy_code',description:'Check supported Arduino syntax without starting the program or modifying the circuit.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){const p=compile(editor.value);return{valid:true,functions:Object.keys(p.functions),circuit:checkCircuit(wires,active())};}}])Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}
